import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that uses a bit array and multiple hash functions to 
    efficiently check the existence of items while allowing a specified false positive rate.

    Design Choices:
    - The size of the bit array is calculated using the number of expected items and desired 
      false positive rate to balance space and accuracy.
    - The number of hash functions is determined to optimize the number of bits set against the 
      number of items to be added, minimizing the false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate
        self.size = self._calculate_size()
        self.num_hashes = self._calculate_num_hashes()
        self.bit_array = [0] * self.size

    def _calculate_size(self) -> int:
        """Calculate the size of the bit array needed for the Bloom Filter."""
        return math.ceil(-(self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _calculate_num_hashes(self) -> int:
        """Calculate the optimal number of hash functions to use."""
        return math.ceil((self.size / self.expected_items) * math.log(2))

    def _hashes(self, item: str) -> list:
        """Generate a list of hash values for the item using different salt values."""
        return [int(hashlib.md5((item + str(i)).encode()).hexdigest(), 16) % self.size for i in range(self.num_hashes)]

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for hash_value in self._hashes(item):
            self.bit_array[hash_value] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        return all(self.bit_array[hash_value] for hash_value in self._hashes(item))

