class BloomFilter:
    """
    A Bloom Filter implementation using a dynamic bit array simulation and custom hash function.
    This version focuses on using a linear probing method to manage bits and employs a consistent hashing strategy 
    to achieve a uniform distribution of hash values.

    Design Choices:
    - The bit array is implemented as a list of booleans for simplicity and clarity.
    - Hash values are computed with consistency through concatenated item representations to avoid collisions.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate
        self.size = self._calculate_size()
        self.num_hashes = self._calculate_num_hashes()
        self.bit_array = [False] * self.size

    def _calculate_size(self) -> int:
        """Calculate the size of the bit array for the Bloom Filter."""
        return math.ceil(-(self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _calculate_num_hashes(self) -> int:
        """Calculate the number of hash functions based on size and expected items."""
        return max(1, min(30, math.ceil((self.size / self.expected_items) * math.log(2))))

    def _hash(self, item: str, seed: int) -> int:
        """Creates a hash value for the item using a seed to ensure unique outputs."""
        return int(hashlib.sha256((item + str(seed)).encode('utf-8')).hexdigest(), 16) % self.size)

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for i in range(self.num_hashes):
            index = self._hash(item, i)
            self.bit_array[index] = True

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        return all(self.bit_array[self._hash(item, i)] for i in range(self.num_hashes))

import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation using a custom bit array represented as an integer and multiple hash functions 
    generated from a simple yet effective combination strategy. This design minimizes space used while simplifying 
    the bit manipulation by representing the bit array as a single integer.

    Design Choices:
    - The bit array is represented as a single integer, which allows us to efficiently set and check bits using bitwise operations.
    - The hash functions are generated based on different seeds to ensure the randomness of their outputs while maintaining
      a direct relation to the item being hashed.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate
        self.size = self._calculate_size()
        self.num_hashes = self._calculate_num_hashes()
        self.bit_array = 0  # Representing bit array as an integer

    def _calculate_size(self) -> int:
        """Calculate the size of the bit array for the Bloom Filter."""
        return math.ceil(-(self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _calculate_num_hashes(self) -> int:
        """Calculate the number of hash functions based on size and expected items."""
        return max(1, min(30, math.ceil((self.size / self.expected_items) * math.log(2))))

    def _hash(self, item: str, seed: int) -> int:
        """Creates a hash value for the item using a seed to ensure distinct outputs."""
        hash_value = int(hashlib.md5((item + str(seed)).encode('utf-8')).hexdigest(), 16)
        return hash_value % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for i in range(self.num_hashes):
            index = self._hash(item, i)
            self.bit_array |= (1 << index)  # Set the bit at index

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom Filter."""
        return all((self.bit_array & (1 << self._hash(item, i))) != 0 for i in range(self.num_hashes))
